#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    int n = (int)readInt(), d = (int)readInt();
    vector<long long> price(n);
    vector<vector<string>> tags(n);
    for (int i = 0; i < n; i++) {
        price[i] = readInt();
        int c = (int)readInt();
        tags[i].resize(c);
        for (auto &t : tags[i]) t = readToken();
    }
    unordered_map<string, pair<int, long long>> disc;
    for (int i = 0; i < d; i++) {
        string k = readToken();
        int t = (int)readInt();
        long long v = readInt();
        disc[k] = {t, v};
    }
    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long best = price[i];
        for (auto &tag : tags[i]) {
            auto it = disc.find(tag);
            if (it == disc.end()) continue;
            auto [t, v] = it->second;
            // 0: fixed new price, 1: percentage off (rounded down), 2: amount off.
            long long x = t == 0 ? v : t == 1 ? price[i] * (100 - v) / 100 : price[i] - v;
            best = min(best, x);
        }
        total += best;
    }
    printf("%lld\n", total);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), d = nextInt();
        long[] price = new long[n];
        String[][] tags = new String[n][];
        for (int i = 0; i < n; i++) {
            price[i] = nextLong();
            tags[i] = new String[nextInt()];
            for (int j = 0; j < tags[i].length; j++) tags[i][j] = next();
        }
        HashMap<String, long[]> disc = new HashMap<>();
        for (int i = 0; i < d; i++) {
            String k = next();
            long t = nextLong(), v = nextLong();
            disc.put(k, new long[] {t, v});
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            long best = price[i];
            for (String tag : tags[i]) {
                long[] e = disc.get(tag);
                if (e == null) continue;
                // 0: fixed new price, 1: percentage off (rounded down), 2: amount off.
                long x = e[0] == 0 ? e[1] : e[0] == 1 ? Math.floorDiv(price[i] * (100 - e[1]), 100) : price[i] - e[1];
                best = Math.min(best, x);
            }
            total += best;
        }
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, d := nextInt(), nextInt()
	price := make([]int, n)
	tags := make([][]string, n)
	for i := 0; i < n; i++ {
		price[i] = nextInt()
		c := nextInt()
		for j := 0; j < c; j++ {
			tags[i] = append(tags[i], string(token()))
		}
	}
	type discount struct{ kind, amount int }
	disc := map[string]discount{}
	for i := 0; i < d; i++ {
		k := string(token())
		disc[k] = discount{nextInt(), nextInt()}
	}
	total := 0
	for i := 0; i < n; i++ {
		best := price[i]
		for _, tag := range tags[i] {
			e, ok := disc[tag]
			if !ok {
				continue
			}
			// 0: fixed new price, 1: percentage off (rounded down), 2: amount off.
			var x int
			switch e.kind {
			case 0:
				x = e.amount
			case 1:
				x = price[i] * (100 - e.amount) / 100
			default:
				x = price[i] - e.amount
			}
			best = min(best, x)
		}
		total += best
	}
	fmt.Println(total)
}
